function v50.semiAquaticRouteWaterContact(p69, p70, ...)
  if not v50.isSemiAquaticRouteMovementCharacter(p69) or not p70 then
    return false, nil, nil
  end

  local gameTerrainWaterHeightAt = v50.gameTerrainWaterHeightAt
      and v50.gameTerrainWaterHeightAt(p70.Position)
    or nil

  if type(gameTerrainWaterHeightAt) == "number" then
    return true, gameTerrainWaterHeightAt, "Terrain"
  end

  local humanoid = p69:FindFirstChildOfClass("Humanoid")

  local isCharacterSwimmingState = v50.isCharacterSwimmingState
      and v50.isCharacterSwimmingState(p69)
    or humanoid and humanoid:GetState() == Enum.HumanoidStateType.Swimming
    or false

  local safeMove = v50.safeMove and v50.safeMove.active == true
      and v50.safeMove.allowWaterTransit == true
      and v50.safeMove.semiAquaticRouteFlyActive == true
      and v50.safeMove.semiAquaticRouteFlyCharacter == p69
    or false

  local v114 = false
  local v115 = nil

  if v50.isUnderMainWaterPart then
    v114, v115 = v50.isUnderMainWaterPart(p70)
  end

  local gameSwimmingGeometry = safeMove and v115 and v115.insideXZ == true
      and v50.gameSwimmingGeometry and v50.gameSwimmingGeometry(p69, p70, v115.topY)
    or false

  if (isCharacterSwimmingState or safeMove) and (v114 or gameSwimmingGeometry) and v115
    and type(v115.topY) == "number" then
    return true, v115.topY, "MainWaterPart"
  end

  if (isCharacterSwimmingState or safeMove) and v50.gameWaterSurfaceHeightAt then
    local v116, v117 = v50.gameWaterSurfaceHeightAt(p70.Position)

    if type(v116) == "number"
        and (p70.Position.Y < v116 + 0.75
          or safeMove and v50.gameSwimmingGeometry and v50.gameSwimmingGeometry(p69, p70, v116))
      or false then
      return true, v116, v117 or "Global"
    end
  end

  return false, nil, nil
end

