function v50.dinoSemiAquaticPointWaterHeight(p73, ...)
  if typeof(p73) ~= "Vector3" then
    return nil, nil
  end

  local gameTerrainWaterHeightAt2 = v50.gameTerrainWaterHeightAt
      and v50.gameTerrainWaterHeightAt(p73)
    or nil

  if type(gameTerrainWaterHeightAt2) == "number" then
    return gameTerrainWaterHeightAt2, "Terrain"
  end

  local y = nil
  local v118 = nil
  local mainWaterPart = workspace:FindFirstChild("MainWaterPart")

  if mainWaterPart and mainWaterPart:IsA("BasePart") then
    local pointToObjectSpace = mainWaterPart.CFrame:PointToObjectSpace(p73)

    if math.abs(pointToObjectSpace.X) <= mainWaterPart.Size.X * 0.5
      and math.abs(pointToObjectSpace.Z) <= mainWaterPart.Size.Z * 0.5 then
      y = mainWaterPart.CFrame:PointToWorldSpace(Vector3.new(
        pointToObjectSpace.X, mainWaterPart.Size.Y * 0.5, pointToObjectSpace.Z
      )).Y

      v118 = "MainWaterPart"
    end
  end

  if type(y) ~= "number" and v50.gameWaterSurfaceHeightAt then
    y, v118 = v50.gameWaterSurfaceHeightAt(p73)
  end

  if type(y) ~= "number" then
    return nil, nil
  end

  local landSlopeTerrainHeightAt = v50.landSlopeTerrainHeightAt
      and v50.landSlopeTerrainHeightAt(p73, y)
    or nil

  if type(landSlopeTerrainHeightAt) == "number" and landSlopeTerrainHeightAt >= y - 0.35 then
    return nil, nil
  end

  return y, v118 or "Global"
end

