function v50.gameTerrainWaterHeightAt(p78, ...)
  if typeof(p78) ~= "Vector3" then
    return nil
  end

  local raycastParams = RaycastParams.new()
  raycastParams.FilterType = Enum.RaycastFilterType.Include
  raycastParams.FilterDescendantsInstances = { workspace.Terrain }
  raycastParams.IgnoreWater = false

  local globalWaterLevelHeight = workspace:GetAttribute("GlobalWaterLevelHeight")

  local v121 = math.max(p78.Y + 180, type(globalWaterLevelHeight) == "number" and globalWaterLevelHeight + 180
    or p78.Y + 180)

  local raycast = workspace:Raycast(
    Vector3.new(p78.X, v121, p78.Z), Vector3.new(0, -500, 0), raycastParams
  )

  if raycast and raycast.Material == Enum.Material.Water then
