    and (v50.questGrowthReset.busy
      or v50.questGrowthReset.active
      or v50.questGrowthReset.preparing
      or p1955 and v50.questGrowthQuestIncomplete(p1953)
        and v50.isGrowthComplete(p1955:GetAttribute("GrowthPercentage"))) then
