function v50.questBuildActiveStatus(p1959, ...)
  if not v50.autoQuests then
    return v50.hudEnglishStatus(autoQuests), 1
  end

  p1959 = type(p1959) == "table" and p1959 or v50._getAllQuests()
  local v4910 = f203()
  local character173 = localPlayer.Character
  local animalName31 = character173 and character173:GetAttribute("AnimalName")

  if (type(animalName31) ~= "string" or animalName31 == "") and character173 then
    animalName31 = v105.getAnimalName(character173)
  end

  local v4911 = v50._getPlayerZoneName()
  local v4912 = v50.questGroup.resolveHandler()
  local v4913 = v4912 and v50.questGroup.getCurrentPack(v4912) or nil
  local v4914 = {}

  for index395, value464 in ipairs(p1959) do
    if v50.questShouldShowInLive(value464, v4910, character173, animalName31, v4911, v4913) then
      local v4915 = tostring(value464.props.Title or value464.entry.QuestUniqueKey or "Quest")
      local v4916 = v50.questFormatProgress(value464) or "In progress"
      local growExisting = ""

      if value464.props.QuestType == "ZoneTime" then
        local v4917 = v50._findZoneInQuest(value464)

        if v4917 then
          growExisting = " · " .. v4917
        end
      elseif v48 and value464.props.QuestType == "NestTime" then
        if v50.questNest and v50.questNest.switchPhase then
          growExisting = " · " .. tostring(v50.questNest.switchPhase)
        elseif character173 and f25(character173) and v50.questGrowthConcurrentActive() then
          growExisting = v50.growExisting and " · Waiting for Grow Existing"
            or " · Waiting for Auto Grow"
        else
          growExisting = v50.questNest and v50.questNest.mode == "zone" and " · Nest + Zone"
            or " · Nest pending"
        end
      elseif value464.props.QuestType == "GroupTime" and v4913 then
        growExisting = string.format(" · %d animals", v50.questGroup.memberCount(v4913))
      elseif v50._isSwimQuest(value464.props) then
        growExisting = " · Swimming"
      elseif v50._isLandDistanceQuest(value464.props) then
        local questLandWWatch6 = v50.questLandWWatch
        local quest3 = v50.aiSupervisorCanDriveOwner("Quest")

        local questLandPermanentWHasFreshSteer = v50.autoRunMoveOwnsInput == true and questLandWWatch6.planReady == true and v50.questLandPermanentWHasFreshSteer and v50.questLandPermanentWHasFreshSteer(
          character173, 0.75
        ) or v50.safeMove and v50.safeMove.active and v50.safeMove.landQuestW == true

        if quest3 and v50.questMotionMoving == true and v50.questMotionMode == "Land"
          and questLandPermanentWHasFreshSteer
          and tick() - (questLandWWatch6.lastPhysicalProgressAt or 0) <= 1.75 then
          growExisting = " · Running"
        elseif questLandWWatch6.executionStatus == "Avoiding obstacle" then
          growExisting = " · Avoiding obstacle"
        elseif questLandWWatch6.executionStatus == "Replanning" then
          growExisting = " · Replanning"
        elseif questLandWWatch6.executionStatus == "Paused" or not quest3 then
          growExisting = " · Paused"
        else
          growExisting = " · Pending"
        end
      elseif v50.questIsGrowthQuest(value464) then
        local v4918 = character173 and tonumber(character173:GetAttribute("GrowthPercentage"))
          or nil

        if v4918 ~= nil and v50.isGrowthComplete(v4918)
          and v50.questGrowthQuestIncomplete(value464) then
          if v50.questGrowthReset.exclusive or v50.questGrowthReset.busy
            or v50.questGrowthReset.preparing then
            growExisting = " · Resetting 100% slot"
          else
            growExisting = " · Reset required"
          end
        elseif v4918 ~= nil and not v50.isGrowthComplete(v4918) then
          growExisting = " · Growing"
        else
          growExisting = " · Selecting Growth slot"
        end
      end

      table.insert(v4914, "• " .. v4915 .. "  —  " .. v4916 .. growExisting)

      if v48 and value464.props.QuestType == "NestTime" then
        table.insert(v4914, "  Auto Nest helper: adult female herbivore only.")

        table.insert(
          v4914, "  Carnivores cannot do Nest alone; a matching Zone quest is required."
        )
      end
    end
  end

  if #v4914 == 0 then
    return v50.hudEnglishStatus(autoQuests), 1
  end

  return table.concat(v4914, "\n"), #v4914
    + (v48 and v50.questNest and v50.questNest.switchPhase
        and math.clamp(math.ceil(#v50.questNest.switchPhase / 35), 1, 3)
      or 0)
