  local v4928 = v50.questUpdateMotionTarget(p1971, p1972, p1974)
  local assemblyLinearVelocity35 = p1972.AssemblyLinearVelocity
  local magnitude132 = Vector3.new(assemblyLinearVelocity35.X, 0, assemblyLinearVelocity35.Z).Magnitude
  local targetSpeed = v4928.targetSpeed
  local acceleration = v4928.acceleration
  local v4929 = math.max(acceleration, targetSpeed * 1.8, 14)
  local v4930 = math.max(p1975 or 0.05, 0.01)
  local v4931

  if magnitude132 < targetSpeed then
    v4931 = math.min(targetSpeed, magnitude132 + v4929 * v4930)
  else
