    function v50.deathReportUI.render(...)
      if not v50.deathReportUI.list or not v50.deathReportUI.list.Parent then
        return
      end

      for index457, value547 in ipairs(v50.deathReportUI.list:GetChildren()) do
        if value547 ~= v50.deathReportUI.layout and value547 ~= v50.deathReportUI.padding then
          value547:Destroy()
        end
      end

      local deathReports = v50.slotGuardian and v50.slotGuardian.deathReports or {}

      if #deathReports == 0 then
        local textLabel9 = Instance.new("TextLabel")
        textLabel9.Size = UDim2.new(1, 0, 0, 66)
        textLabel9.BackgroundColor3 = color3
        textLabel9.BorderSizePixel = 0
        textLabel9.Font = gotham
        textLabel9.Text = "No slot events recorded."
        textLabel9.TextColor3 = color8
        textLabel9.TextSize = userInputService.TouchEnabled and 13 or 14
        textLabel9.ZIndex = 53
        textLabel9.Parent = v50.deathReportUI.list

        f248(textLabel9, 9)
        return
      end

      for index458, value548 in ipairs(deathReports) do
        local v5694 = v50.deathReportUI.selectedReport == value548

        local textButton3 = Instance.new("TextButton")
        textButton3.Size = UDim2.new(1, -2, 0, v5694 and 390 or 78)
        textButton3.LayoutOrder = index458
        textButton3.BackgroundColor3 = v5694 and color4 or color3
        textButton3.BorderSizePixel = 0
        textButton3.Text = ""
        textButton3.AutoButtonColor = false
        textButton3.ZIndex = 53
        textButton3.Parent = v50.deathReportUI.list

        f248(textButton3, 9)

        local textLabel10 = Instance.new("TextLabel")
        textLabel10.Size = UDim2.fromOffset(34, 34)
        textLabel10.Position = UDim2.fromOffset(10, 22)
        textLabel10.BackgroundColor3 = color4
        textLabel10.BorderSizePixel = 0
        textLabel10.Font = Enum.Font.GothamBlack

        textLabel10.Text = value548.eventType == "planned_slot_transition" and "↔"
          or value548.classification == "saved_growth_preserved" and "✓"
          or value548.classification == "slot_outcome_unverified" and "?"
          or value548.classification == "growth_changed_during_slot_transaction" and "?"
          or "☠"

        textLabel10.TextColor3 = color5
        textLabel10.TextSize = 16
        textLabel10.ZIndex = 54
        textLabel10.Parent = textButton3

        f248(textLabel10, 7)

        local textLabel11 = Instance.new("TextLabel")
        textLabel11.Size = UDim2.new(1, -56, 0, 28)
        textLabel11.Position = UDim2.fromOffset(54, 10)
        textLabel11.BackgroundTransparency = 1
        textLabel11.Font = gothamSemibold

        textLabel11.Text = tostring(value548.slot or "Unknown slot") .. "  ·  "
          .. tostring(value548.animal or "Unknown animal")

        textLabel11.TextColor3 = color7
        textLabel11.TextSize = userInputService.TouchEnabled and 13 or 14
        textLabel11.TextXAlignment = Enum.TextXAlignment.Left
        textLabel11.TextTruncate = Enum.TextTruncate.AtEnd
        textLabel11.ZIndex = 54
        textLabel11.Parent = textButton3

        local textLabel12 = Instance.new("TextLabel")
        textLabel12.Size = UDim2.new(1, -56, 0, 26)
        textLabel12.Position = UDim2.fromOffset(54, 42)
        textLabel12.BackgroundTransparency = 1
        textLabel12.Font = gotham

        textLabel12.Text = (value548.eventType == "planned_slot_transition"
              and (value548.resetConfirmed and "Planned reset · " or "Reset unconfirmed · ")
            or value548.classification == "saved_growth_preserved" and "Growth preserved · "
            or value548.classification == "saved_growth_loss_confirmed"
              and "Saved growth fell · "
            or value548.classification == "slot_outcome_unverified"
              and "Slot outcome unverified · "
            or value548.classification == "growth_changed_during_slot_transaction"
              and "Growth changed during slot switch · "
            or "")
          .. tostring(value548.when or "Unknown time")

        textLabel12.TextColor3 = color8
        textLabel12.TextSize = userInputService.TouchEnabled and 12 or 13
        textLabel12.TextXAlignment = Enum.TextXAlignment.Left
        textLabel12.ZIndex = 54
        textLabel12.Parent = textButton3

        if v5694 then
          local textLabel13 = Instance.new("TextLabel")
          textLabel13.Size = UDim2.new(1, -20, 0, 292)
          textLabel13.Position = UDim2.fromOffset(10, 88)
          textLabel13.BackgroundTransparency = 1
          textLabel13.Font = gotham
          textLabel13.TextColor3 = color8
          textLabel13.TextSize = userInputService.TouchEnabled and 11 or 12
          textLabel13.TextWrapped = true
          textLabel13.TextXAlignment = Enum.TextXAlignment.Left
          textLabel13.TextYAlignment = Enum.TextYAlignment.Top
          textLabel13.ZIndex = 54

          local slotStateAfter18s = value548.slotStateAfter18s or value548.slotStateAfter

          local v5695 = {
            "EVENT: " .. tostring(value548.eventType or "legacy death report"),
            "CLASSIFICATION: " .. tostring(value548.classification or "not recorded"),
            "SAVED SLOT AFTER: "
              .. tostring(slotStateAfter18s and slotStateAfter18s.subjectSaved or "not checked"),
            "ACTIVE SLOT AFTER: "
              .. tostring(slotStateAfter18s and slotStateAfter18s.activeSlot or "not checked"),
            "ZONE: " .. tostring(value548.zone or "Not captured (older report)"),
            "MODE: " .. tostring(value548.mode or "Not captured (older report)"),
            "SIGNAL: " .. tostring(value548.reason or "Not captured"), "",
          }

          local growthVerification = value548.growthVerification

          if type(growthVerification) == "table" then
            table.insert(v5695, "GROWTH BEFORE: "
              .. tostring(growthVerification.baseline or growthVerification.beforeSaved
                or growthVerification.beforeLive or "?"))

            table.insert(v5695, "GROWTH AFTER: " .. tostring(growthVerification.after or "?"))

            table.insert(v5695, "GROWTH VERDICT: "
              .. tostring(growthVerification.verdict or "unverified"))

            table.insert(v5695, "")
          end

          if value548.captureError then
            table.insert(v5695, "DIAGNOSTIC CAPTURE ERROR: " .. tostring(value548.captureError))
            table.insert(v5695, "")
          end

          local vitals = type(value548.vitals) == "table" and value548.vitals or {}
          local v5696 = vitals[#vitals]

          if v5696 then
            table.insert(v5695, "AT HUMANOID EVENT: HP " .. tostring(v5696.health or "?") .. " | Food "
              .. tostring(v5696.food or "?") .. "% | Water " .. tostring(v5696.water or "?")
              .. "%")

            table.insert(v5695, "BODY " .. tostring(v5696.position or "?") .. " | water target "
              .. tostring(v5696.waterTarget or "?"))

            table.insert(v5695, "CONTROL: route=" .. tostring(v5696.route or "none") .. " busy="
              .. tostring(v5696.busy) .. " arbiter=" .. tostring(v5696.arbiter or "none")
              .. " supervisor=" .. tostring(v5696.authority or "none"))

            table.insert(v5695, "ROUTE TARGET: " .. tostring(v5696.routeTarget or "?"))
            table.insert(v5695, "")
            table.insert(v5695, "VITAL TREND (seconds before Humanoid event, oldest first)")

            for index459, value549 in ipairs(vitals) do
              table.insert(v5695, string.format(
                "-%.1fs HP %s Food %s Water %s | %s | %s", tonumber(value549.age) or 0,
                tostring(value549.health or "?"), tostring(value549.food or "?"),
                tostring(value549.water or "?"), tostring(value549.route or "none"),
                tostring(value549.position or "?")
              ))
            end

            table.insert(v5695, "")
          end

          local drinkAttempts = type(value548.drinkAttempts) == "table"
              and value548.drinkAttempts
            or {}

          if #drinkAttempts > 0 then
            table.insert(v5695, "REX/CARNO DRINK ATTEMPTS (oldest first)")

            for index460, value550 in ipairs(drinkAttempts) do
              table.insert(v5695, string.format(
                "%02d. -%.1fs %s | %s | Water %s -> %s | %.1fs", index460,
                tonumber(value550.age) or 0, tostring(value550.source or "?"),
                tostring(value550.result or "?"), tostring(value550.initialWater or "?"),
                tostring(value550.lastWater or "?"), tonumber(value550.duration) or 0
              ))

              table.insert(v5695, "  prompts start=" .. tostring(value550.startSeen == true) .. " stop="
                .. tostring(value550.stopSeen == true) .. " last="
                .. tostring(value550.lastPrompt or "?") .. " | E taps="
                .. tostring(value550.taps or 0) .. " | Drinking calls="
                .. tostring(value550.subStateCalls or 0) .. " | corrections="
                .. tostring(value550.corrections or 0))

              table.insert(v5695, "  body=" .. tostring(value550.lastPosition or "?") .. " mouth="
                .. tostring(value550.mouthPosition or "?") .. " ["
                .. tostring(value550.mouthName or "?") .. "]" .. " stand="
                .. tostring(value550.standPoint or "?") .. " water="
                .. tostring(value550.waterPoint or "?"))
            end

            table.insert(v5695, "")
          end

          local waterRepairs = type(value548.waterRepairs) == "table" and value548.waterRepairs
            or {}

          if #waterRepairs > 0 then
            table.insert(v5695, "WATER RECOVERY CALLS (return is not proof of movement)")

            for index461, value551 in ipairs(waterRepairs) do
              table.insert(v5695, string.format(
                "-%.1fs call=%s route %s -> %s busy=%s lease=%s arbiter=%s",
                tonumber(value551.age) or 0, tostring(value551.returned == true),
                tostring(value551.routeBefore or "none"),
                tostring(value551.routeAfter or "none"), tostring(value551.busy == true),
                tostring(value551.lease or "none"), tostring(value551.arbiter or "none")
              ))
            end

            table.insert(v5695, "")
          end

          table.insert(v5695, "LAST 10 STATUS MESSAGES BEFORE HUMANOID EVENT")
          local messages = type(value548.messages) == "table" and value548.messages or {}

          local messageAges = type(value548.messageAges) == "table" and value548.messageAges
            or nil

          if #messages == 0 then
            table.insert(v5695, "No message history captured for this report.")
          elseif messageAges and #messageAges == #messages then
            for i115 = math.max(1, #messages - 9), #messages do
              table.insert(v5695, string.format(
                "%02d. -%.1fs %s", i115, tonumber(messageAges[i115]) or 0,
                tostring(messages[i115])
              ))
            end
          else
            local v5697 = math.max(1, #messages - 9)
            local v5698 = {}

            for i116 = v5697, #messages do
              local v5699 = tostring(messages[i116])
              local v5700

              for index462, value552 in ipairs(v5698) do
                if value552.message == v5699 then
                  v5700 = index462
                  break
                end
              end

              if v5700 then
                local v5701 = table.remove(v5698, v5700)
                v5701.count = v5701.count + 1
                table.insert(v5698, v5701)
              else
                table.insert(v5698, { message = v5699, count = 1 })
              end
            end

            for index463, value553 in ipairs(v5698) do
              table.insert(v5695, string.format("%02d. %s%s", index463, value553.message, value553.count > 1
                  and string.format(" (%dx)", value553.count)
                or ""))
            end
          end

          textLabel13.Text = table.concat(v5695, "\n")
          local v5702 = math.max(170, v50.deathReportUI.list.AbsoluteSize.X - 42)

          local v5703, v5704 = pcall(
            textService.GetTextSize, textService, textLabel13.Text, textLabel13.TextSize,
            textLabel13.Font, Vector2.new(v5702, 10000)
          )

          local v5705 = v5703 and math.max(292, v5704.Y + 20) or math.max(292, #v5695 * 20)
          textLabel13.Size = UDim2.new(1, -20, 0, v5705)
          textButton3.Size = UDim2.new(1, -2, 0, v5705 + 98)
          textLabel13.Parent = textButton3
        end

        textButton3.Activated:Connect(function(...)
          v50.deathReportUI.selectedReport = v50.deathReportUI.selectedReport == value548
              and nil
            or value548

          v50.deathReportUI.render()
        end)
      end
    end

